// Decides whether a geocoded address is inside the pickup service area.
//
// Full-coverage ZIP codes accept any address. Partial-coverage ZIP codes also
// require the address to fall inside that ZIP code's polygon in
// treeRecyclingServiceArea.json, generated by scripts/build-service-area.py
// from boundary roads and water. Each polygon extends a little beyond the ZIP
// code's edges, so the ZIP code check remains the outer limit.
import serviceAreaJson from "../../config/treeRecyclingServiceArea.json";
import { settings, type TreeRecyclingSettings } from "./settings";

type Ring = [number, number][]; // [longitude, latitude] pairs
type PolygonCoords = Ring[];

interface AreaFeature {
  properties: { zip: string; description: string };
  geometry:
    | { type: "Polygon"; coordinates: PolygonCoords }
    | { type: "MultiPolygon"; coordinates: PolygonCoords[] };
}

const areas = (serviceAreaJson as unknown as { features: AreaFeature[] }).features;

function inRing(lng: number, lat: number, ring: Ring): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
}

function inPolygon(lng: number, lat: number, polygon: PolygonCoords): boolean {
  const [outer, ...holes] = polygon;
  return inRing(lng, lat, outer) && !holes.some((hole) => inRing(lng, lat, hole));
}

export interface ServiceAreaResult {
  inArea: boolean;
  /** For partial ZIP codes, which part we serve, e.g. "North of Oswego Lake". */
  coverageNote?: string;
}

export function checkServiceArea(
  zip: string,
  lat: number,
  lng: number,
  s: TreeRecyclingSettings = settings,
): ServiceAreaResult {
  const coverage = s.zipCodes[zip.slice(0, 5)];
  if (!coverage) {
    return { inArea: false };
  }
  if (coverage === "full") {
    return { inArea: true };
  }

  const area = areas.find((a) => a.properties.zip === zip.slice(0, 5));
  if (!area) {
    // A partial ZIP code without a drawn boundary: refuse rather than guess.
    return { inArea: false };
  }
  const polygons =
    area.geometry.type === "Polygon"
      ? [area.geometry.coordinates]
      : area.geometry.coordinates;
  return {
    inArea: polygons.some((p) => inPolygon(lng, lat, p)),
    coverageNote: area.properties.description,
  };
}
